INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-i-ieu-1','qclv-chuong-i','Điều 1','Phạm vi điều chỉnh và đối tượng áp dụng','1. Phạm vi điều chỉnh

Quy chế này quy định nguyên tắc làm việc; chức năng, nhiệm vụ các phòng; quyền hạn, trách nhiệm, cách thức giải quyết công việc; chế độ làm việc; mối quan hệ công tác; trình tự giải quyết công việc của Ban QLDA đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh (sau đây gọi tắt là Ban QLDA).

2. Đối tượng áp dụng

Quy chế này áp dụng đối với tất cả viên chức (VC), người lao động (NLĐ) của Ban QLDA.

Các tổ chức, cá nhân bên ngoài khi đến làm việc, liên hệ công tác với Ban QLDA phải chấp hành quy định của Ban QLDA và các quy định liên quan trong phạm vi trách nhiệm, quyền hạn của mình.','text',1),('chuong-i-ieu-2','qclv-chuong-i','Điều 2','Nguyên tắc làm việc','1. Ban QLDA làm việc theo nguyên tắc tập trung dân chủ, thực hiện chế độ thủ trưởng, đảm bảo sự chỉ đạo, điều hành thống nhất của Giám đốc đối với các lĩnh vực công tác của Ban QLDA, phát huy quyền làm chủ của VC, NLĐ gắn với sự lãnh đạo của Đảng và phát huy vai trò của các tổ chức đoàn thể trong cơ quan. Mọi hoạt động của Ban QLDA tỉnh đều phải tuân thủ quy định của pháp luật và Quy chế này. VC, NLĐ thuộc Ban QLDA phải xử lý và giải quyết công việc đúng phạm vi trách nhiệm, thẩm quyền;

2. Chấp hành nghiêm túc sự chỉ đạo của Giám đốc và Phó Giám đốc phụ trách. Khi giải quyết, xử lý công việc, đơn vị trình trực tiếp Phó Giám đốc phụ trách. Trường hợp Phó Giám đốc phụ trách đi vắng thì đơn vị trình Giám đốc (hoặc Phó Giám đốc được Giám đốc phân công) xem xét xử lý và đơn vị đó phải báo cáo kết quả xử lý cho Phó Giám đốc phụ trách khi Phó Giám đốc phụ trách có mặt ở cơ quan;

3. Trong phân công công việc, mỗi việc chỉ được giao một đơn vị, một cá nhân phụ trách và chịu trách nhiệm chính. Đơn vị, người đứng đầu đơn vị được giao công việc phải chịu trách nhiệm về tiến độ và kết quả công việc được phân công. Cấp trên không làm thay công việc của cấp dưới, tập thể không làm thay công việc của cá nhân và ngược lại;

4. Bảo đảm tuân thủ trình tự, thủ tục và thời hạn giải quyết công việc theo đúng quy định của pháp luật, chương trình, kế hoạch, lịch làm việc và Quy chế làm việc, trừ trường hợp đột xuất hoặc có yêu cầu khác của cơ quan cấp trên;

5. Bảo đảm phát huy năng lực và sở trường của VC, NLĐ, đề cao sự phối hợp công tác, trách nhiệm làm việc nhóm, phát huy trí tuệ tập thể và trao đổi thông tin trong giải quyết công việc và trong mọi hoạt động theo chức năng, nhiệm vụ, quyền hạn được pháp luật quy định;

6. Bảo đảm dân chủ, rõ ràng, minh bạch và hiệu quả trong mọi hoạt động.','text',2),('chuong-ii-ieu-3','qclv-chuong-ii','Điều 3','Cơ cấu tổ chức Ban QLDA','Theo Quyết định của UBND tỉnh: Số 1865/QĐ-UBND ngày 22/7/2025 về việc thành lập Ban Quản lý dự án đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh và Ban Quản lý dự án đầu tư xây dựng công trình Nông nghiệp và Phát triển nông thôn tỉnh Hà Tĩnh trên cơ sở tách Ban Quản lý dự án đầu tư xây dựng công trình Nông nghiệp và Dân dụng tỉnh Hà Tĩnh, tổ chức bộ máy của Ban QLDA gồm:

\- Ban Giám đốc gồm có: Giám đốc và 03 Phó Giám đốc;

\- Các Phòng trực thuộc có 07 phòng: Hành chính – Tổng hợp, Kế hoạch – Đấu thầu, Kỹ thuật – Thẩm định, Quản lý dự án 1, Quản lý dự án 2, Quản lý dự án 3 và Phát triển dịch vụ.','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-ii-ieu-4','qclv-chuong-ii','Điều 4','Chức năng, nhiệm vụ và quyền hạn của Ban QLDA','Chức năng, nhiệm vụ và quyền hạn của Ban QLDA thực hiện theo Quyết định số 2760/QĐ-UBND ngày 06/11/2025 của UBND tỉnh Hà Tinh về việc Quy định Chức năng, nhiệm vụ và quyền hạn của Ban QLDA.','text',2),('chuong-ii-ieu-5','qclv-chuong-ii','Điều 5','Chức năng nhiệm vụ của các phòng trực thuộc Ban QLDA','1. **Phòng Hành chính – Tổng hợp**

1.1. Chức năng của phòng Hành chính – Tổng hợp

Tham mưu, giúp Giám đốc Ban chỉ đạo, điều hành công việc và duy trì

chế độ làm việc tại cơ quan; trực tiếp tham mưu Giám đốc Ban về công tác hành chính – quản trị; công tác tổ chức bộ máy, quản lý viên chức và người lao động;

Tham mưu, giúp Giám đốc Ban tổ chức thực hiện công tác quản lý tài

chính, tài sản, chế độ kế toán và sử dụng có hiệu quả, đúng mục đích các nguồn

tài chính của Ban theo quy định của Nhà nước và pháp luật.

1.2. Nhiệm vụ của Phòng Hành chính – Tổng hợp

a) Công tác Hành chính \- Quản trị','text',3),('chuong-iii-ieu-6','qclv-chuong-iii','Điều 6','Quyền hạn, trách nhiệm của Giám đốc Ban QLDA','1. Là người đứng đầu, phụ trách chung, lãnh đạo, chỉ đạo, điều hành và quản lý toàn diện mọi hoạt động của Ban QLDA theo chức năng, nhiệm vụ, quyền hạn; chịu trách nhiệm trước UBND tỉnh, Chủ tịch UBND tỉnh và trước pháp luật về toàn bộ hoạt động thuộc thẩm quyền của Ban;

2. Chỉ đạo tổ chức triển khai tất cả các dự án được cấp có thẩm quyền giao cho Ban QLDA làm Chủ đầu tư hoặc của các Chủ đầu tư khác thông qua hợp đồng tư vấn quản lý dự án;

3. Ban hành Quy chế làm việc, quy định cụ thể chức năng, nhiệm vụ, quyền hạn của các phòng trực thuộc, mối liên hệ công tác giữa các phòng và các quy chế khác đảm bảo công tác quản lý điều hành;

4. Ban hành Đề án vị trí việc làm theo đúng quy định; phân công, bố trí, sắp xếp hợp lý đội ngũ viên chức đúng cơ cấu, đảm bảo tiêu chuẩn ngạch và khung năng lực theo từng vị trí việc làm đã phê duyệt; phân công công việc cho các Phó Giám đốc, trên cơ sở năng lực, kinh nghiệm công tác của các Phó Giám đốc; ủy quyền cho một Phó Giám đốc điều hành hoạt động của Ban QLDA khi giám đốc vắng mặt; uy quyền cho các Phó Giám đốc, Trưởng, phó các phòng trực thuộc Ban QLDA thực hiện một số công việc cụ thể trong khuôn khổ pháp luật;

5. Chỉ đạo, kiểm tra, giám sát và đôn đốc tổ chức, cá nhân và các Phòng trực thuộc Ban QLDA trong việc thực hiện các nhiệm vụ đã phân công;

6. Phụ trách công tác quản lý tài chính; công tác tổ chức bộ máy, quản lý cán bộ, viên chức, người lao động, chế độ chính sách; công tác đào tạo, bồi dưỡng, thi đua \- khen thưởng, kỷ luật, kỷ cương hành chính, công tác bảo vệ chính trị nội bộ; công tác quản lý kế hoạch \- đầu tư \- đấu thầu, nguồn vốn đầu tư xây dựng; công tác thanh tra, kiểm tra, kiểm toán; công tác phòng, chống tham nhũng, lãng phí, thực hành tiết kiệm; công tác tiếp công dân và giải quyết khiếu nại, tố cáo; chiến lược, kế hoạch phát triển chung về đầu tư xây dựng công trình;

7. Tổ chức, chủ trì các cuộc họp định kỳ và đột xuất (nếu có) của Ban Quản lý dự án, đôn đốc, kiểm tra, giám sát việc thực hiện nhiệm vụ công tác của các phòng và của các thành viên Ban QLDA;

8. Ký các văn bản trình Thường trực Tỉnh uỷ, Thường trực HĐND tỉnh, UBND tỉnh và Chủ tịch UBND tỉnh. Ký các văn bản, hợp đồng xây dựng, hồ sơ có liên quan đến các dự án với các nhà thầu được lựa chọn; ký các chứng từ thanh toán, tạm ứng; ký hợp đồng làm việc đối với viên chức, hợp đồng lao động với các lao động hợp đồng tại Ban QLDA;

9. Là người phát ngôn của Ban QLDA hoặc ủy quyền cho Phó Giám đốc phát ngôn, cung cấp thông tin của đơn vị cho báo chí và các cơ quan chức năng khi có yêu cầu;

10. Trực tiếp giải quyết một số công việc đã phân công cho Phó Giám đốc phụ trách trong các trường hợp: nội dung vấn đề cấp bách, quan trọng; Phó Giám đốc đi công tác vắng; hoặc các vấn đề liên quan đến từ hai Phó Giám đốc trở lên nhưng còn có ý kiến khác nhau;

11. Những công việc cần thảo luận tập thể Lãnh đạo Ban QLDA trước khi Giám đốc quyết định:

a) Chiến lược, quy hoạch, kế hoạch phát triển Ban QLDA;','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-iii-ieu-7','qclv-chuong-iii','Điều 7','Quyền hạn, trách nhiệm của Phó Giám đốc Ban QLDA','1. Tham mưu, giúp việc cho Giám đốc, được Giám đốc phân công phụ trách một số lĩnh vực công tác và phụ trách các phòng chuyên môn theo Quyết định phân công nhiệm vụ các thành viên Ban Giám đốc; thay mặt Giám đốc giải quyết công việc trong phạm vi được giao và chịu trách nhiệm trước Giám đốc, UBND tỉnh, Chủ tịch UBND tỉnh và trước pháp luật về kết quả thực hiện nhiệm vụ theo lĩnh vực được giao; đồng thời, cùng chịu trách nhiệm về các nội dung tập thể do lãnh đạo Ban quyết định;

2. Chủ động phân công nhiệm vụ, bố trí viên chức, người lao động thực hiện các nhiệm vụ chuyên môn đối với các phòng được giao phụ trách; tham mưu, đề xuất về việc điều chuyển, bãi nhiệm, miễn nhiệm, xử lý kỷ luật viên chức, người lao động thuộc lĩnh vực phụ trách khi để xảy ra vi phạm ảnh hưởng nghiêm trọng đến tiến độ, chất lượng công việc chung;

3. Các Phó Giám đốc khi được giao QLDA chủ trì, chỉ đạo phòng Quản lý dự án 1, 2, 3 đề xuất nhân sự Tổ thực hiện công trình/dự án (nếu cần thiết) và phòng Kế hoạch \- Đấu thầu đề xuất nhân sự Tổ chuyên gia đấu thầu trình Giám đốc Ban QLDA thành lập;

4. Tham gia các cuộc họp, đề xuất hoặc kiến nghị về các giải pháp, biện pháp cần thiết để thực hiện các nhiệm vụ của Ban Quản lý dự án;

5. Giúp Giám đốc chỉ đạo, điều hành, hướng dẫn, đôn đốc, kiểm tra và xử lý công việc theo sự phân công, ủy quyền của Giám đốc; chịu trách nhiệm trước Giám đốc, trước pháp luật và cơ quan nhà nước cấp trên về việc thực hiện nhiệm vụ được giao;

6. Đối với những vấn đề thuộc về chủ trương hoặc có tính nguyên tắc mà chưa có văn bản quy định hoặc những vấn đề nhạy cảm dễ gây tác động lớn và những vấn đề quan trọng khác thì Phó Giám đốc phải xin ý kiến Giám đốc trước khi quyết định;

7. Phó Giám đốc được phân công phụ trách các phòng chuyên môn, chương trình, dự án hoặc lĩnh vực nào thì được duyệt, ký văn bản thuộc lĩnh vực đó (trừ những văn bản, Quyết định, tờ trình ... thuộc thẩm quyền của Giám đốc Ban được quy định tại Điều 3 Quy chế này) ; đối với những quyết định vượt quá thẩm quyền, Phó Giám đốc phải báo cáo xin ý kiến Giám đốc trước khi chỉ đạo thực hiện; ký các văn bản, hợp đồng xây dựng, hồ sơ có liên quan đến các dự án với các nhà thầu được lựa chọn khi được Giám đốc Ban QLDA ủy quyền;

8. Khi Phó Giám đốc phụ trách vắng mặt, Giám đốc trực tiếp hoặc phân công Phó Giám đốc khác giải quyết công việc của Phó Giám đốc vắng mặt và thông báo lại;

9. Trong phạm vi nhiệm vụ, quyền hạn được phân công, chủ động giải quyết công việc và phối hợp với các Phó Giám đốc khác; trường hợp còn có ý kiến khác nhau hoặc có nội dung quan trọng thì Phó Giám đốc được phân công báo cáo Giám đốc trước khi quyết định, đảm bảo không làm chậm trễ công việc;

10. Thực hiện các nhiệm vụ khác khi được UBND tỉnh, Chủ tịch UBND tỉnh giao, Giám đốc Ban giao.','text',2),('chuong-iii-ieu-8','qclv-chuong-iii','Điều 8','Trách nhiệm, quyền hạn của Trưởng phòng các phòng trực thuộc Ban QLDA','1. Chủ động tổ chức thực hiện công việc thuộc chức năng, nhiệm vụ, quyền hạn của Phòng; chịu trách nhiệm trước Giám đốc, Phó Giám đốc phụ trách và pháp luật về kết quả và tiến độ thực hiện công việc được giao bao gồm cả nhiệm vụ phân công cho cấp dưới. Thực hiện đầy đủ chế độ thông tin, báo cáo theo quy định của pháp luật và của Ban QLDA;

2. Những việc phát sinh vượt quá thẩm quyền phải kịp thời báo cáo Phó Giám đốc phụ trách hoặc Giám đốc Ban QLDA khi Phó giám đốc phụ trách đi vắng, xin ý kiến chỉ đạo giải quyết; không chuyển công việc thuộc nhiệm vụ, thẩm quyền của phòng mình sang phòng khác hoặc lên lãnh đạo Ban; không giải quyết công việc thuộc nhiệm vụ, thẩm quyền của phòng khác khi chưa có chỉ đạo của lãnh đạo Ban;

3. Chủ trì tham mưu xây dựng, góp ý văn bản quy phạm pháp luật, chính sách, kế hoạch chiến lược thuộc lĩnh vực được giao phụ trách;

4. Chủ động phối hợp với các Trưởng phòng khác thuộc Ban QLDA để xử lý những vấn đề có liên quan đến những công việc thuộc chức năng, nhiệm vụ của phòng và thực hiện nhiệm vụ chung của Ban QLDA;

5. Chủ trì theo dõi, đôn đốc, chịu trách nhiệm thực hiện kết luận của Thanh tra, Kiểm toán tại Phòng;

6. Tổ chức thực hiện công việc theo đúng Quy chế làm việc của Ban QLDA; phân công nhiệm vụ cụ thể cho cấp phó và nhân viên đơn vị mình;

7. Khi vắng mặt 01 ngày phải được sự đồng ý của Phó Giám đốc phụ trách lĩnh vực và phải ủy quyền cho cấp phó phòng quản lý, điều hành công việc của đơn vị, đồng thời thông báo cho Phòng Hành chính \- Tổng hợp biết. Người được ủy quyền phải chịu trách nhiệm trước Trưởng phòng, Phó giám đốc phụ trách, Giám đốc Ban QLDA và trước pháp luật về hoạt động của đơn vị trong thời gian ủy quyền;

8. Trưởng phòng được phép cho nhân viên thuộc đơn vị mình nghỉ 1/2 ngày khi có công việc đột xuất; nếu nghỉ từ 1 ngày thì phải báo cáo Phòng Hành chính \- Tổng hợp và Phó Giám đốc phụ trách;

9. Khi được lãnh đạo Ban ủy quyền tham dự các cuộc họp do cấp trên tổ chức, chậm nhất sau 01 ngày kể từ ngày kết thúc cuộc họp phải báo cáo đầy đủ nội dung của cuộc họp với Phó Giám đốc phụ trách, đối với nội dung quan trọng phải đồng thời báo cáo Giám đốc;

10. Kiểm tra, rà soát, ký nháy và chịu trách nhiệm đối với các dự thảo văn bản của phòng trước khi trình lãnh đạo Ban;

11.Thực hiện những nhiệm vụ khác do Giám đốc Ban QLDA hoặc Phó Giám đốc Ban QLDA giao.','text',3),('chuong-iii-ieu-9','qclv-chuong-iii','Điều 9','Trách nhiệm, quyền hạn của Phó Trưởng phòng các phòng chuyên môn thuộc Ban QLDA','1. Phó Trưởng phòng trực tiếp thực hiện nhiệm vụ chuyên môn được phân công; giúp Trưởng phòng phụ trách, chỉ đạo, quản lý một số công tác, lĩnh vực công việc cụ thể theo sự phân công của Trưởng phòng; chịu trách nhiệm trước Trưởng phòng, Phó giám đốc phụ trách, Giám đốc Ban và pháp luật về thực hiện nhiệm vụ được giao;

2. Thực hiện trách nhiệm, quyền hạn của Trưởng phòng khi được ủy quyền;

3. Theo sự phân công của Trưởng phòng, tham gia tổ chức quản lý, điều hành các công tác của phòng; phân công, hỗ trợ, đôn đốc các nhân viên thuộc đơn vị thực hiện hoàn thành các nhiệm vụ được giao; Báo cáo Trưởng phòng kết quả thực hiện nhiệm vụ được phân công, ủy quyền;

4. Kiểm tra, soát xét, ký nháy và chịu trách nhiệm đối với các dự thảo văn bản của phòng trình Lãnh đạo Ban khi được Trưởng phòng phân công;

5. Thực hiện các nhiệm vụ khác do Trưởng phòng và lãnh đạo Ban giao.','text',4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-iii-ieu-10','qclv-chuong-iii','Điều 10','Quyền hạn và trách nhiệm của Kế toán trưởng','1. Tổ chức bộ máy kế toán, thực hiện nhiệm vụ, quyền hạn theo Luật Kế toán, theo các các Nghị định của Chính phủ, các thông tư hướng dẫn của Bộ Tài chính và các quy định hiện hành; trực tiếp phân công nhiệm vụ cho các kế toán viên; chịu trách nhiệm chuyên môn về công tác kế toán;

2. Được bảo đảm về điều kiện làm việc, được đào tạo nâng cao trình độ chuyên môn, nghiệp vụ và được hưởng các quyền lợi theo quy định của pháp luật;

3. Chịu sự quản lý, giám sát, phân công công việc của Lãnh đạo phòng Hành chính \- Tổng hợp (trừ các công việc chuyên môn thuộc thẩm quyền của Kế toán trưởng); chịu trách nhiệm trước Giám đốc, Chủ tịch Ủy ban nhân dân tỉnh và trước pháp luật về nhiệm vụ được giao.','text',5),('chuong-iii-ieu-11','qclv-chuong-iii','Điều 11','Quyền, nghĩa vụ, trách nhiệm của viên chức, người lao động:','1. Được bảo đảm về điều kiện làm việc, được đào tạo nâng cao trình độ chuyên môn nghiệp vụ và được hưởng các quyền lợi theo quy định pháp luật;

2. Có quyền đề xuất đóng góp ý kiến, các biện pháp để thực hiện hiệu quả nhiệm vụ được giao;

3. Có trách nhiệm thực hiện và hoàn thành nhiệm vụ được giao, chấp hành nghiêm quy định pháp luật, chính sách hiện hành và quy chế làm việc của Ban QLDA;

4. Chịu trách nhiệm cá nhân trước Tổ trưởng/Lãnh đạo phòng/Ban Giám đốc Ban QLDA và trước pháp luật về ý kiến đề xuất, tiến độ, chất lượng, hiệu quả của từng công việc được giao; về hình thức, thể thức, trình tự và thủ tục ban hành văn bản và quy trình giải quyết công việc được phân công theo dõi;

5. Thực hiện các quy định của pháp luật về viên chức, hợp đồng lao động, các quy định của Ban QLDA tỉnh và của phòng;

6. Thực hiện tốt mối quan hệ phối hợp công tác với các viên chức và người lao động trong các phòng; xây dựng và thực hiện chương trình công tác mà cá nhân đề ra; thường xuyên trau dồi kiến thức, học tập nâng cao trình độ chuyên môn, nghiệp vụ, rèn luyện đạo đức, lối sống;

7. Có trách nhiệm bảo quản, sử dụng tiết kiệm, hiệu quả tài sản của Ban QLDA;

8. Bảo vệ bí mật nhà nước, bí mật công tác và các nội dung bảo mật theo đúng quy định của pháp luật và theo Quy chế của Ban QLDA;

9. Tuân thủ đúng nội quy, quy chế của đơn vị;

10. Quyền và nghĩa vụ đối với lao động hợp đồng của Ban QLDA: Thực hiện theo điều khoản hợp đồng ký kết;

11. Viên chức, NLĐ không được tham gia, can thiệp vào các quyết định có xung đột lợi ích với bản thân, người thân; phải báo cáo lãnh đạo Ban khi có nguy cơ xung đột lợi ích theo quy định PCTN.','text',6),('chuong-iv-ieu-12','qclv-chuong-iv','Điều 12','Cách thức giải quyết công việc','1. Giám đốc và các Phó Giám đốc điều hành công việc trên cơ sở chương trình, kế hoạch công tác của Ban QLDA; tình hình thực tế; yêu cầu chỉ đạo của UBND tỉnh, các sở, ban, ngành; và các nhiệm vụ đột xuất (nếu có);

2. Giám đốc, Phó Giám đốc chủ trì họp, làm việc với lãnh đạo các cơ quan, tổ chức có liên quan để tham khảo ý kiến trước khi quyết định những vấn đề quan trọng hoặc còn vướng mắc chưa xử lý được ngay;

3. Khi trình hồ sơ giải quyết công việc cho Lãnh đạo Ban, cán bộ thụ lý hồ sơ phải có Tờ trình/Văn bản và đầy đủ hồ sơ kèm theo; đồng thời thực hiện xử lý công việc thông qua phần mềm hồ sơ quản lý công việc (TDO);

4. Lãnh đạo phòng, viên chức, người lao động chỉ được xử lý công việc sau khi lãnh đạo Ban QLDA đã có ý kiến chỉ đạo cụ thể trên phiếu trình hoặc thông qua phần mềm hồ sơ quản lý công việc.','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-iv-ieu-13','qclv-chuong-iv','Điều 13','Trách nhiệm của các phòng trực thuộc trong việc trình Lãnh đạo Ban QLDA giải quyết hồ sơ công việc','1. Các phòng trực thuộc chỉ trình Giám đốc, Phó Giám đốc những vấn đề thuộc phạm vi giải quyết của Giám đốc, Phó Giám đốc khi có đủ các hồ sơ theo quy định.

2. Khi trình Giám đốc, Phó Giám đốc, các phòng trực thuộc có nhiệm vụ:

a) Thẩm định về mặt thủ tục: Nếu hồ sơ công việc trình không đúng theo quy định, phải hướng dẫn ngay cho cá nhân, đơn vị đã nộp hồ sơ để bổ sung thủ tục đầy đủ. Đối với những vấn đề cần giải quyết gấp, các phòng trực thuộc làm phiếu báo cho đơn vị trình bổ sung thêm hồ sơ, đồng thời báo cho Giám đốc, Phó Giám đốc phụ trách được biết;','text',2),('chuong-iv-ieu-14','qclv-chuong-iv','Điều 14','Tiếp nhận, xử lý và ban hành văn bản','1. Quy trình tiếp nhận, xử lý và ban hành văn bản phải tuân thủ theo quy định pháp luật về công tác văn thư và Quy định tiếp nhận, xử lý, ban hành văn bản tại Ban QLDA;

2. Các phòng chuyên môn, cán bộ Ban QLDA phải kiểm tra và chịu trách nhiệm về độ chính xác của văn bản; Đối với dự toán/dự toán điều chỉnh, báo cáo, … có file excel đính kèm, thì bắt buộc phải gửi file pdf để ban hành kèm theo;	3. Trưởng bộ phận chuyên môn phải kiểm tra và chịu trách nhiệm về hình thức, thể thức, kỹ thuật trình bày và thủ tục ban hành văn bản theo đúng quy định của pháp luật, đồng thời phải ký nháy vào văn bản tham mưu ban hành.','text',3),('chuong-iv-ieu-15','qclv-chuong-iv','Điều 15','Quy định về sử dụng dấu của cơ quan','1. Việc quản lý, sử dụng con dấu được thực hiện theo quy định của pháp luật về quản lý và sử dụng con dấu.

2. Nhân viên văn thư có trách nhiệm bảo quản, sử dụng con dấu theo đúng quy định và có trách nhiệm.

a) Không giao con dấu cho người khác khi chưa được phép bằng văn bản của người có thẩm quyền;','text',4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-v-ieu-16','qclv-chuong-v','Điều 16','Quan hệ công tác giữa Ban QLDA với UBND tỉnh, Chủ tịch UBND tỉnh','1. Chịu sự chỉ đạo, kiểm tra, giám sát trực tiếp của UBND tỉnh, Chủ tịch UBND tỉnh về thực hiện chức năng, nhiệm vụ được giao;

2. Trình cấp quyết định đầu tư phê duyệt các nội dung thuộc trách nhiệm của chủ đầu tư theo nhiệm vụ được giao và theo quy định của pháp luật;

3. Báo cáo định kỳ hoặc đột xuất về tình hình triển khai thực hiện các dự án được giao quản lý; đề xuất biện pháp xử lý những vấn đề vượt quá thẩm quyền giải quyết của mình;

4. Giải trình các nội dung cần thiết theo yêu cầu của UBND tỉnh, Chủ tịch UBND tỉnh;

5. Phối hợp với các cơ quan, đơn vị chức năng của UBND tỉnh trong việc thực hiện các nhiệm vụ quản lý dự án.','text',1),('chuong-v-ieu-17','qclv-chuong-v','Điều 17','Quan hệ công tác giữa Ban QLDA với các Sở, ban ngành thuộc tỉnh','1. Khi giải quyết vấn đề thuộc thẩm quyền của mình nhưng có liên quan đến chức năng của các Sở, ban, ngành khác thì chủ động tham khảo ý kiến các cơ quan đó;

2. Đối với các vấn đề vượt thẩm quyền và khả năng giải quyết của Ban QLDA tỉnh hoặc những vấn đề đã được bàn bạc nhưng còn có ý kiến khác nhau giữa các sở, ban ngành, UBND các phường/xã thì báo cáo Chủ tịch/Phó Chủ tịch UBND tỉnh (trưởng Ban chỉ đạo dự án) phụ trách lĩnh vực giải quyết.

3. Báo cáo, giải trình về tình hình thực hiện quản lý dự án khi được yêu cầu, về sự cố công trình, an toàn trong xây dựng với cơ quan nhà nước có thẩm quyền và đề xuất biện pháp phối hợp xử lý những vấn đề vượt quá thẩm quyền;

4. Chịu sự kiểm tra, giám sát của cơ quan nhà nước có thẩm quyền theo quy định của pháp luật. Chủ động phối hợp chặt chẽ và thường xuyên với các sở, ban, ngành và đoàn thể, với chủ đầu tư dự án để giải quyết công việc kịp thời.','text',2),('chuong-v-ieu-18','qclv-chuong-v','Điều 18','Quan hệ công tác giữa Ban QLDA với UBND các phường/xã.','1. Giám đốc Ban QLDA làm việc trực tiếp với Chủ tịch UBND các phường/xã để giải quyết các vấn đề cụ thể của phường/xã có liên quan đến chức năng của Ban QLDA. Khi Giám đốc ủy quyền cho các Phó Giám đốc, Trưởng/Phụ trách các phònglàm việc với Chủ tịch UBND các phường/xã thì những ý kiến của người được ủy quyền được coi là ý kiến của Giám đốc;

2. Trường hợp đề nghị của UBND các phường/xã liên quan đến nhiều ngành, thì Ban QLDA phải chủ động phối hợp với các sở, ban, ngành liên quan để xử lý. Trường hợp các cơ quan không thống nhất hoặc còn có ý kiến khác nhau thì báo cáo Chủ tịch/Phó Chủ tịch UBND tỉnh (trưởng Ban chỉ đạo dự án) phụ trách lĩnh vực giải quyết;

3. Phối hợp với UBND cấp xã trong việc thực hiện công tác bồi thường, giải phóng mặt bằng, tái định cư khi dự án có yêu cầu về thu hồi đất để xây dựng; quản lý hành chính, bảo đảm an ninh, trật tự, an toàn của cộng đồng trong quá trình thực hiện dự án và bàn giao công trình vào khai thác, sử dụng.','text',3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-v-ieu-19','qclv-chuong-v','Điều 19','Quan hệ công tác giữa Ban QLDA với chủ đầu tư các dự án thực hiện quản lý dự án, chủ quản lý sử dụng công trình','1. Thực hiện các quyền, nghĩa vụ đối với các chủ đầu tư, chịu sự kiểm tra, giám sát của chủ đầu tư trong quá trình thực hiện quản lý các dự án theo hợp đồng ký kết và theo quy định của pháp luật có liên quan;

2. Phối hợp với chủ quản lý sử dụng công trình khi lập, phê duyệt nhiệm vụ thiết kế xây dựng công trình, trong quá trình tổ chức thực hiện dự án, nghiệm thu, bàn giao công trình xây dựng hoàn thành vào vận hành, sử dụng (kể cả việc thực hiện bảo hành công trình theo quy định);

3. Bàn giao công trình xây dựng hoàn thành cho chủ đầu tư hoặc chủ quản lý sử dụng theo quy định của pháp luật; quản lý công trình xây dựng hoàn thành trong thời gian chưa xác định được đơn vị quản lý sử dụng công trình theo yêu cầu của người quyết định đầu tư;

4. Thực hiện các nhiệm vụ tư vấn quản lý dự án của chủ đầu tư theo ủy quyền và theo quy định của pháp luật có liên quan.','text',4),('chuong-v-ieu-20','qclv-chuong-v','Điều 20','Quan hệ công tác giữa Ban QLDA với nhà thầu','1. Tổ chức lựa chọn nhà thầu thực hiện các gói thầu thuộc dự án do mình làm chủ đầu tư hoặc được thuê làm tư vấn quản lý dự án; đàm phán, ký kết và thực hiện hợp đồng với nhà thầu được lựa chọn theo quy định của pháp luật;

2. Thực hiện các quyền, nghĩa vụ của chủ đầu tư đối với nhà thầu xây dựng theo quy định của hợp đồng xây dựng và quy định của pháp luật có liên quan;

3. Tiếp nhận, xử lý theo thẩm quyền hoặc kiến nghị cấp có thẩm quyền giải quyết các đề xuất, vướng mắc của nhà thầu trong quá trình thực hiện.','text',5),('chuong-v-ieu-21','qclv-chuong-v','Điều 21','Quan hệ công tác giữa Ban QLDA với các đơn vị tiếp nhận tài sản, hưởng lợi','1. Phối hợp với Các đơn vị tiếp nhận tài sản, hưởng lợi tham gia vào quá trình thực hiện dự án bao gồm công tác giải phóng mặt bằng (nếu có), chuẩn bị dự án, giám sát quá trình thực hiện, tiếp nhận và duy tu bảo dưỡng, vận hành công trình. Giám đốc Ban QLDA có thẩm quyền ra quyết định thành lập các ban, tổ công tác gồm các thành phần trên để phối hợp trong quá trình triển khai thực hiện dự án và sử dụng, duy tu bảo dưỡng, vận hành công trình;

2. Các chế độ, chính sách liên quan (nếu có) của các cán bộ đơn vị hưởng lợi thực hiện theo quy định của pháp luật và quy chế của dự án.','text',6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-v-ieu-22','qclv-chuong-v','Điều 22','Quan hệ giữa Lãnh đạo Ban QLDA đối với các phòng thuộc Ban QLDA','1. Giám đốc, Phó Giám đốc phụ trách lĩnh vực/các phòng, định kỳ hoặc đột xuất họp với lãnh đạo các phòng hoặc làm việc với từng phòng, để trực tiếp nghe báo cáo tình hình, chỉ đạo việc thực hiện chương trình, kế hoạch công tác của các phòng thuộc Ban QLDA;

2. Trưởng/phụ trách các phòng có trách nhiệm báo cáo kịp thời với Ban Giám đốc Ban QLDA về kết quả thực hiện, kiến nghị các vấn đề cần giải quyết liên quan đến hoạt động của phòng mình và những khó khăn vướng mắc cần tháo gỡ, kiến nghị với cấp có thẩm quyền về sửa đổi, điều chỉnh cơ chế chính sách.','text',7),('chuong-v-ieu-23','qclv-chuong-v','Điều 23','Quan hệ giữa các phòng trực thuộc Ban QLDA','1. Trưởng các phòng được giao chủ trì giải quyết các vấn đề có liên quan với các phòng khác phải trao đổi ý kiến với các phòng đó. Trưởng/phụ trách các phòng được xin ý kiến có trách nhiệm trả lời theo đúng yêu cầu của phòng chủ trì;

2. Theo phân công của Ban Giám đốc Ban QLDA, Trưởng/phụ trách các phòng có trách nhiệm phối hợp thực hiện các dự án, chương trình của Ban QLDA. Đối với những vấn đề liên quan đến nhiều phòng mà vượt quá thẩm quyền giải quyết hoặc không đủ điều kiện thì Trưởng/Phụ trách phòng chủ trì báo cáo, đề xuất với lãnh đạo Ban QLDA xem xét quyết định;

3. Thực hiện theo nguyên tắc: Công việc thuộc phạm vi chức năng, nhiệm vụ của phòng nào thì phòng đó chủ trì, tham mưu; chủ động phối hợp với các phòng có liên quan để thực hiện chức năng, nhiệm vụ, quyền hạn được giao. Các phòng liên quan có trách nhiệm phối hợp, trường hợp có ý kiến khác nhau thì phòng chủ trì báo cáo Ban Giám đốc xem xét, quyết định;

4. Tuân thủ đúng Quy chế làm việc của Ban QLDA; việc phối hợp có thể bằng văn bản hoặc qua trao đổi trực tiếp đảm bảo yêu cầu về chuyên môn, chất lượng và tiến độ thời gian trong quá trình phối hợp;

5. Bảo đảm kỷ luật, kỷ cương trong hoạt động phối hợp, đề cao trách nhiệm cá nhân của Trưởng/Phụ trách phòng chủ trì và cán bộ, viên chức, người lao động của phòng được phối hợp.','text',8),('chuong-v-ieu-24','qclv-chuong-v','Điều 24','Các mối quan hệ khác','1. Quan hệ làm việc giữa Giám đốc Ban QLDA với các Bộ, ngành Trung ương, Tỉnh ủy, Hội đồng nhân dân, Ủy ban nhân dân tỉnh, các cơ quan tổ chức chính trị \- xã hội, tổ chức xã hội nghề nghiệp thuộc ngành lĩnh vực thực hiện theo quy định của pháp luật và các quy định có liên quan;

2. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với Đảng ủy Ban QLDA tỉnh thực hiện theo quy định của Đảng và Quy chế làm việc của Ban Chấp hành Đảng bộ Ban QLDA;

3. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với Công đoàn Ban QLDA tỉnh được thực hiện theo Quy chế phối hợp giữa Ban Giám đốc với Công đoàn Ban QLDA tỉnh;

4. Quan hệ giữa Lãnh đạo Ban QLDA tỉnh với các tổ chức đoàn thể và cán bộ, viên chức, người lao động trong Ban QLDA:

a) Lãnh đạo Ban QLDA tỉnh tạo điều kiện thuận lợi cho Cấp ủy, các tổ chức đoàn thể hoạt động theo đúng Điều lệ, tôn chỉ mục đích; phối hợp với cấp ủy và các tổ chức quần chúng tạo điều kiện thuận lợi cho cán bộ làm việc, nâng cao trình độ chính trị, chuyên môn nghiệp vụ trong đơn vị, bảo đảm thực hiện Quy chế dân chủ trong hoạt động của cơ quan, xây dựng nề nếp văn hóa công sở và kỷ luật, kỷ cương hành chính;','text',9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-vi-ieu-25','qclv-chuong-vi','Điều 25','Chế độ hội họp','1. Chế độ họp, giao ban nội bộ

a) Chế độ họp với UBND tỉnh, Chủ tịch UBND tỉnh: Thực hiện theo quy định chung của tỉnh;','text',1),('chuong-vi-ieu-26','qclv-chuong-vi','Điều 26','Chế độ báo cáo','1. Ban QLDA thực hiện chế độ báo cáo định kỳ và đột xuất với UBND tỉnh, Chủ tịch UBND tỉnh và theo yêu cầu của các cơ quan có thẩm quyền;

2. Chế độ báo cáo trong nội bộ Ban QLDA

a) Phó Giám đốc báo cáo giám đốc:','text',2),('chuong-vi-ieu-27','qclv-chuong-vi','Điều 27','Chế độ kiểm tra, giám sát','1. Chế độ kiểm tra, giám sát đầu tư đối với dự án được giao Chủ đầu tư

a) Tổ chức thực hiện theo dõi, kiểm tra toàn bộ quá trình đầu tư dự án theo nội dung và chỉ tiêu được phê duyệt nhằm đảm bảo mục tiêu và hiệu quả đầu tư;','text',3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-vi-ieu-28','qclv-chuong-vi','Điều 28','Cung cấp thông tin hoạt động trong nội bộ Ban QLDA tỉnh','Lãnh đạo Ban QLDA tỉnh và các phòng liên quan có trách nhiệm thông báo bằng hình thức thích hợp, thuận tiện để cán bộ Ban QLDA tỉnh nắm được những thông tin:

1. Chủ trương, chính sách của Đảng, Nhà nước, UBND tỉnh liên quan đến công việc của Ban QLDA tỉnh;

2. Tuyển dụng, đào tạo, khen thưởng, kỷ luật, nâng bậc lương, nâng ngạch, bổ nhiệm cán bộ;

3. Văn bản kết luận về việc giải quyết khiếu nại, tố cáo;

4. Nội quy, quy chế làm việc của Ban QLDA tỉnh và các văn bản liên quan khác.','text',4),('chuong-vi-ieu-29','qclv-chuong-vi','Điều 29','Thời gian làm việc, chế độ nghỉ phép, nghỉ việc riêng','1. Thời gian làm việc

Cán bộ, viên chức, người lao động có trách nhiệm:

a) Thực hiện nghiêm túc thời gian làm việc theo Luật Lao động và giờ hành chính theo thông báo của UBND tỉnh; giữ gìn vệ sinh nơi làm việc, bảo quản tài sản chung của cơ quan và tài sản được giao sử dụng; sẵn sàng đáp ứng mọi yêu cầu để hoàn thành tốt nhiệm vụ được giao;','text',5),('chuong-vi-ieu-30','qclv-chuong-vi','Điều 30','Đi công tác trong và ngoài nước','1. Khi Lãnh đạo Ban đi công tác, các phòng liên quan có trách nhiệm chuẩn bị nội dung, tài liệu phục vụ; Phòng Hành chính – Tổng hợp chuẩn bị điều kiện cần thiết và công tác hậu cần cho chuyến công tác;

2. Cán bộ, viên chức, người lao động đi công tác phải xây dựng chương trình, kế hoạch, trong đó ghi rõ nội dung, địa điểm (trong nước hoặc quốc gia/vùng lãnh thổ đến), thời gian công tác, trình Trưởng/Phụ trách phòng báo cáo Giám đốc xem xét, quyết định;

3. Trường hợp tham gia đoàn công tác liên ngành hoặc đoàn công tác của tỉnh, việc cử cán bộ, viên chức, người lao động tham gia phải đúng thành phần theo yêu cầu;

4. Việc đi công tác nước ngoài được thực hiện theo quy định của pháp luật và Quy chế quản lý thống nhất các hoạt động đối ngoại của tỉnh;

5. Chế độ công tác phí và các khoản chi khác thực hiện theo Quy chế chi tiêu nội bộ của Ban QLDA và quy định hiện hành của Nhà nước.','text',6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-vi-ieu-31','qclv-chuong-vi','Điều 31','Khen thưởng, kỷ luật, giải quyết khiếu nại, tố cáo liên quan cán bộ, viên chức, người lao động; công tác phòng chống tham nhũng','1. Khen thưởng, kỷ luật

a) Chế độ khen thưởng thường xuyên, đột xuất hàng năm thực hiện theo Quy chế thi đua, khen thưởng của Ban QLDA và theo quy định của pháp luật;','text',7),('chuong-vii-ieu-32','qclv-chuong-vii','Điều 32','Hiệu lực thi hành','1. Quy chế làm việc có hiệu lực từ ngày ban hành. Quy chế này được phổ biến, quán triệt đến toàn thể cán bộ, viên chức và người lao động thuộc Ban QLDA tỉnh để thực hiện.

2. Giám đốc, Phó Giám đốc, các phòng trực thuộc, các viên chức, người lao động Ban QLDA có trách nhiệm thực hiện Quy chế này. Giám đốc Ban QLDA có trách nhiệm phân công nhiệm vụ cụ thể cho các Phó Giám đốc, các phòng trực thuộc và viên chức, người lao động phù hợp với thực tiễn hoạt động của Ban QLDA đảm bảo đúng quy định của pháp luật và các quy định tại Quy chế này.

3. Trong quá trình tổ chức thực hiện, trường hợp các quy định tại Quy chế này có thay đổi do văn bản pháp luật mới ban hành hoặc có nội dung khác với quy định của cấp có thẩm quyền, thì thực hiện theo quy định của pháp luật hiện hành; hoặc nếu có vấn đề vướng mắc trưởng/phụ trách các phòng kịp thời báo cáo Lãnh đạo Ban QLDA (qua phòng Hành chính \- Tổng hợp) để nghiên cứu sửa đổi, bổ sung cho phù hợp./.

|  | BAN QLDA ĐẦU TƯ XÂY DỰNG  CÔNG TRÌNH DÂN DỤNG  VÀ HẠ TẦNG KHU VỰC |

| :---- | :---: |','text',1),('chuong-chung-dieu-1','qcdgxl-chung','chuong-chung-dieu-1','Điều 1. Ban hành kèm theo Quyết định này Quy chế Đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh.','content: ( )','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-chung-dieu-2','qcdgxl-chung','chuong-chung-dieu-2','Điều 2. Quyết định này có hiệu lực kể từ ngày ban hành.','content: ( )','text',2),('chuong-chung-dieu-3','qcdgxl-chung','chuong-chung-dieu-3','Điều 3. Trưởng các phòng: Hành chính \- Tổng hợp, Quản lý dự án 1, Quản lý dự án 2, Quản lý dự án 3, Kế hoạch \- Đấu thầu, Kỹ thuật \- Thẩm định, Phát triển dịch vụ và các tổ chức, cá nhân có liên quan chịu trách nhiệm thi hành Quyết định này./.','| *Nơi nhận:*		         	     	 - Như điều 2; - Giám đốc, các Phó Giám đốc; - Lưu VT, HC-TH./.  | GIÁM ĐỐC Nguyễn Quang Linh  |

| :---- | ----- |

| UBND TỈNH HÀ TĨNH BAN QLDA ĐẦU TƯ XÂY DỰNG CÔNG TRÌNH DÂN DỤNG VÀ HẠ TẦNG KHU VỰC  | CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc  |

| ----- | :---: |

#

# **QUY CHẾ**

**Đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình**

**Dân dụng** **và Hạ tầng khu vực tỉnh Hà Tĩnh**

#','text',3),('chuong-i-dieu-1','qcdgxl-chuong-i','chuong-i-dieu-1','Điều 1. Phạm vi điều chỉnh và đối tượng áp dụng','1. Phạm vi điều chỉnh: Quy chế này quy định việc đánh giá, xếp loại hàng tháng lấy cơ sở đánh giá, xếp loại hàng năm và chi thu nhập tăng thêm đối với các phòng; cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh (Ban QLDA).

2. Đối tượng áp dụng: Viên chức, người lao động và các phòng chuyên môn thuộc Ban QLDA.','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-i-dieu-2','qcdgxl-chuong-i','chuong-i-dieu-2','Điều 2. Mục đích','1. Tiêu chí đánh giá, xếp loại hàng tháng của viên chức, người lao động Ban QLDA là căn cứ để bình xét khen thưởng, chi trả thu nhập tăng thêm hàng năm; là căn cứ để đánh giá, xếp loại thi đua; đồng thời là cơ sở để bố trí, sử dụng, quy hoạch, đề bạt, đào tạo, bồi dưỡng và thực hiện chính sách đối với cán bộ, viên chức, người lao động theo quy định và theo yêu cầu nhiệm vụ của cơ quan.

2. Đánh giá xếp loại hàng tháng đối với cán bộ, viên chức, người lao động nhằm phát huy vai trò, trách nhiệm của người đứng đầu trong công tác lãnh đạo, quản lý, siết chặt kỷ luật, kỷ cương, chuẩn hóa, xây dựng phong cách làm việc chuyên nghiệp; nâng cao ý thức trách nhiệm, tính tự giác trong thực thi công vụ của cán bộ, viên chức, người lao động; tạo môi trường sáng tạo, đổi mới, phát triển, nâng cao chất lượng, hiệu quả hoạt động của cơ quan.','text',2),('chuong-i-dieu-3','qcdgxl-chuong-i','chuong-i-dieu-3','Điều 3. Yêu cầu','1. Căn cứ vào Kế hoạch khung hàng năm của Ban QLDA, nhiệm vụ chuyên môn của các phòng và khối lượng công việc tồn đọng, các phòng thuộc Ban QLDA phải xây dựng kế hoạch công tác tháng, quý, năm; phân công cụ thể (cán bộ trực tiếp phụ trách, lãnh đạo phòng trực tiếp quản lý, lãnh đạo Ban phụ trách); nội dung công việc được giao; tiến độ, thời gian thực hiện, hoàn thành; xác định kết quả đầu ra của mỗi nhiệm vụ được giao. Trên cơ sở kế hoạch công tác của phòng, cá nhân xây dựng kế hoạch thực hiện tháng, quý, năm.

2. Việc đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, lao động phải thực hiện theo nguyên tắc tập trung dân chủ, chính xác, khách quan, công bằng, đúng thực chất và đúng trình tự quy định. Phải thực hiện đánh giá đa chiều, liên tục, lượng hóa được kết quả thực hiện nhiệm vụ của từng cán bộ, viên chức, người lao động gắn với kết quả công tác của từng bộ phận, từng phòng chuyên môn (trên cơ sở phân tích về tổng khối lượng và tính chất, mức độ của công việc).','text',3),('chuong-i-dieu-4','qcdgxl-chuong-i','chuong-i-dieu-4','Điều 4. Nguyên tắc đánh giá, xếp loại chất lượng','1. Trưởng các phòng trực tiếp lãnh đạo, giao nhiệm vụ, đồng thời là người thực hiện nhận xét, đánh giá, xếp loại viên chức và người lao động thuộc đơn vị mình. Giám đốc Ban QLDA là người đứng đầu cơ quan quyết định việc xếp loại, đánh giá cán bộ, viên chức, người lao động theo phân cấp quản lý và chịu trách nhiệm về quyết định của mình.

2. Việc đánh giá, xếp loại phải căn cứ vào chức trách, nhiệm vụ được giao và kết quả thực hiện nhiệm vụ. Việc đánh giá cần làm rõ ưu điểm, khuyết điểm, tồn tại, hạn chế về phẩm chất, năng lực, trình độ của cán bộ, viên chức, người lao động.

3. Bảo đảm dân chủ, khách quan, chính xác, công khai, minh bạch, xuyên suốt, liên tục, đa chiều.

4. Việc đánh giá, xếp loại viên chức lãnh đạo, quản lý phải dựa vào kết quả hoạt động của cơ quan, đơn vị được giao quản lý, phục trách. Mức độ hoàn thành nhiệm vụ của người đứng đầu không được cao hơn mức độ hoàn thành nhiệm vụ của đơn vị được giao quản lý, phụ trách.

5. Trường hợp cán bộ, viên chức, lao động không hoàn thành nhiệm vụ do yếu tố khách quan, bất khả kháng thì được xem xét trong quá trình đánh giá, xếp loại.','text',4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-i-dieu-5','qcdgxl-chuong-i','chuong-i-dieu-5','Điều 5. Thời hạn định kỳ đánh giá, xếp loại','1. Đối với Ban QLDA tỉnh và các phòng chuyên môn: Thực hiện hằng quý/năm.

2. Đối với viên chức, người lao động: Thực hiện hàng tháng làm cơ sở để đánh giá, xếp loại chất lượng hàng năm.

Đối với Giám đốc, Phó giám đốc Ban QLDA được đánh giá xếp loại hàng quý. Căn cứ vào kết quả đánh giá, xếp loại hàng quý các phòng được giao phụ trách của các Phó Giám đốc và kết quả đánh giá, xếp loại hàng quý của Ban QLDA tỉnh để đề xuất UBND tỉnh đánh giá xếp loại Giám đốc, Phó giám đốc.','text',5),('chuong-i-dieu-6','qcdgxl-chuong-i','chuong-i-dieu-6','Điều 6. Mức đánh giá, xếp loại chất lượng','Cán bộ, viên chức, người lao động được đánh giá, xếp loại chất lượng theo 4 mức:

a) Hoàn thành xuất sắc nhiệm vụ (Loại A1);','text',6),('chuong-ii-dieu-7','qcdgxl-chuong-ii','chuong-ii-dieu-7','Điều 7. Thẩm quyền đánh giá, xếp loại chất lượng','- UBND tỉnh xếp loại đối với Giám đốc, Phó Giám đốc trên cơ sở nhận xét, đánh giá của Hội đồng thi đua khen thưởng, đánh giá, xếp loại Ban QLDA.

- Hội đồng thi đua khen thưởng, đánh giá, xếp loại Ban QLDA xem xét, quyết định kết quả đánh giá, xếp loại viên chức, người lao động; tổ chức nhận xét, đánh giá xếp loại các trưởng phòng, tập thể các phòng; nhận xét, đánh giá Giám đốc, Phó Giám đốc, tập thể Ban QLDA làm cơ sở đề xuất UBND tỉnh xếp loại.

- Trưởng phòng đánh giá, xếp loại hàng tháng đối với phó phòng, viên chức và người lao động thuộc đơn vị.

- Cán bộ, viên chức, người lao động tự đánh giá, xếp loại hàng tháng đối với bản thân.','text',1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-ii-dieu-8','qcdgxl-chuong-ii','chuong-ii-dieu-8','Điều 8. Tiêu chí đánh giá, xếp loại (Thang điểm 100\)','1. Ý thức tổ chức kỷ luật, phẩm chất đạo đức lối sống **(tối đa 20 điểm)**

- Ý thức tổ chức kỷ luật; phẩm chất đạo đức, lối sống, tác phong, lề lối làm việc chuẩn mực **(tối đa 6 điểm).**

- Đoàn kết, thực hiện nguyên tắc tập trung dân chủ trong cơ quan **(tối đa 5 điểm).**

- Thực hiện hiện nghiêm quy tắc ứng xử trong các hoạt động của cơ quan **(tối đa 3 điểm).**

- Thực hiện nghiêm quy định văn hóa công sở, đạo đức công vụ của viên chức, người lao động **(tối đa 6 điểm).**

2. Kết quả thực hiện chức trách nhiệm vụ được giao **(tối đa 75 điểm)**

a) Năng lực và kỹ năng **(tối đa 20 điểm)**','text',2),('chuong-ii-dieu-9','qcdgxl-chuong-ii','chuong-ii-dieu-9','Điều 9. Mức xếp loại','1. Đối với cán bộ, viên chức, người lao động:

- Hoàn thành xuất sắc nhiệm vụ (xếp loại A1): Đạt từ 91 đến 100 điểm.

- Hoàn thành tốt nhiệm vụ (xếp loại A): Đạt từ 71 đến dưới 90 điểm.

- Hoàn thành nhiệm vụ (xếp loại B): Đạt từ 50 đến dưới 70 điểm.

- Không hoàn thành nhiệm vụ (xếp loại C): Dưới 50 điểm.','text',3),('chuong-ii-dieu-10','qcdgxl-chuong-ii','chuong-ii-dieu-10','Điều 10. Một số trường hợp cụ thể trong đánh giá, xếp loại','1. Không đánh giá, xếp loại trong tháng với cán bộ, viên chức, người lao động trong thời gian ký hợp đồng thử việc; nghỉ thai sản; nghỉ ốm, nghỉ do bị tai nạn lao động quá 20/22 ngày làm việc trong tháng; nghỉ việc riêng không hưởng lương quá 15/22 ngày làm việc trong tháng (kể cả nghỉ phép).

2. Đối với cán bộ, viên chức, người lao động có thời gian nghỉ việc từ trên 12 ngày làm việc trong tháng vì lý do ốm đau... thì mức xếp loại của tháng tối đa là hoàn thành nhiệm vụ (xếp loại B).

3. Đối với trường hợp cán bộ, viên chức, người lao động được cử đi đào tạo, bồi dưỡng (hệ không tập trung) mà thời gian làm việc thực tế trong tháng chưa đạt trên 50% số ngày làm việc của tháng thì vẫn thực hiện đánh giá nhưng mức xếp loại tối đa là hoàn thành nhiệm vụ (xếp loại B).

4. Đối với trường hợp viên chức, người lao động được cử đi học tập trung, thoát ly công việc cơ quan trên 30 ngày/năm làm việc thì căn cứ vào kết quả học tập để đánh giá, mức xếp loại tối đa là hoàn thành tốt nhiệm vụ (xếp loại A).

Trường hợp khi chưa có kết quả học tập, tạm thời xếp loại A và khi có kết quả học tập sẽ điều chỉnh xếp loại (Kết quả học tập đạt loại giỏi, loại khá thì xếp loại A; đạt loại trung bình thì xếp loại B; kết quả học tập dưới trung bình hoặc không hoàn thành khóa học thì xếp loại C).

5. Đối với cán bộ, viên chức, người lao động chịu trách nhiệm chính trong xử lý công việc trong tháng khi có văn bản phê bình của cơ quan cấp trên thì mức xếp loại của tháng tối đa là hoàn thành nhiệm vụ (xếp loại B); Lãnh đạo của phòng đó bị hạ 1 bậc xếp loại trong tháng.

6. Trường hợp xếp loại ở mức khác do Giám đốc Ban QLDA xem xét, đánh giá và quyết định.','text',4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-ii-dieu-11','qcdgxl-chuong-ii','chuong-ii-dieu-11','Điều 11. Quy trình, các bước thực hiện đánh giá, xếp loại','Trên cơ sở chức năng nhiệm vụ của đơn vị, khuyến khích Lãnh đạo phòng xây dựng, sửa đổi, bổ sung, điều chỉnh Phiếu đánh giá, xếp loại hàng tháng dành cho cán bộ lãnh đạo quản lý; Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức, người lao động đảm bảo phù hợp, sát với thực tế công tác chuyên môn của đơn vị nhằm đánh giá, xếp loại chính xác, khách quan, công bằng, đúng thực chất gắn với kết quả công tác chuyên môn của từng cá nhân.

- Bước 1: Viên chức, người lao động tự kiểm điểm, nhận mức xếp loại hàng tháng.

- Bước 2: Các phòng chuyên môn tổ chức nhận xét, đánh giá xếp loại viên chức, người lao động hàng tháng trên cơ sở tự xếp loại của các cá nhân. Tiến hành bỏ phiếu kín xếp loại để khẳng định sự tín nhiệm tại cuộc họp chuyên môn của phòng sau lễ chào cờ hàng tháng.

- Bước 3: Gửi kết quả xếp loại hàng tháng đến bộ phận tổng hợp thuộc phòng Hành chính - Tổng hợp trước 10h00 ngày 05 của tháng kế tiếp. Hồ sơ gồm: (i) Biên bản họp đánh giá, xếp loại của phòng; (ii) Danh sách tổng hợp kết quả đánh giá, xếp loại đối với viên chức, người lao động.

- Bước 4: Trên cơ sở kết quả đánh giá, xếp loại hàng tháng, Phòng Hành chính - Tổng hợp kiểm tra, rà soát, tham mưu, tổng hợp kết quả đánh giá, xếp loại trình Hội đồng thi đua, khen thưởng, đánh giá, xếp loại Ban QLDA.

- Bước 5: Ban Giám đốc tổ chức kiểm điểm, tự đánh giá, xếp loại các đ/c trong Ban Giám đốc; Hội đồng thi đua, khen thưởng, đánh giá, xếp loại Ban QLDA xem xét, quyết định kết quả đánh giá, xếp loại của Phó phòng, viên chức, người lao động; tổ chức nhận xét, đánh giá xếp loại các đ/c trong Ban giám đốc; các đ/c trưởng phòng; tập thể các phòng; tập thể Ban QLDA (bằng hình thức bỏ phiếu kín để khẳng định sự tín nhiệm). Mức xếp loại của các đ/c trong Ban giám đốc và lãnh đạo các phòng không cao hơn kết quả xếp loại của đơn vị mình được giao quản lý, phụ trách.

- Bước 6: Công khai kết đánh giá, xếp loại viên chức, người lao động tại Hội nghi viên chức và người lao động hoặc mạng thông tin nội bộ của cơ quan.

Các vấn đề khiếu nại về công tác đánh giá, xếp loại sẽ do Giám đốc Ban QLDA xem xét, quyết định theo quy định về phân cấp quản lý cán bộ.','text',5),('chuong-ii-dieu-12','qcdgxl-chuong-ii','chuong-ii-dieu-12','Điều 12. Khiếu nại, kiến nghị về kết quả xếp loại chất lượng.','1. Khi có cơ sở cho rằng kết quả xếp loại chất lượng không đúng quy định của pháp luật hoặc quy chế đánh giá của đơn vị, viên chức có quyền kiến nghị về kết quả xếp loại chất lượng đối với mình bằng văn bản đến Giám đốc Ban QLDA. Văn bản kiến nghị phải nêu rõ căn cứ kiến nghị, nội dung kiến nghị và đề xuất.

2. Thời hạn kiến nghị là 05 ngày kể từ ngày công khai kết quả xếp loại chất lượng.

3. Cấp có thẩm quyền có trách nhiệm giải quyết kiến nghị bằng hình thức đối thoại hoặc bằng văn bản trong thời hạn 10 ngày làm việc kể từ ngày nhận được kiến nghị.

4. Trình tự, thủ tục giải quyết kiến nghị về kết quả xếp loại chất lượng thực hiện theo quy định tại Điều này và theo quy chế của đơn vị. Không xem xét lại kết quả giải quyết kiến nghị.','text',6),('chuong-ii-dieu-13','qcdgxl-chuong-ii','chuong-ii-dieu-13','Điều 13. Sử dụng kết quả đánh giá, xếp loại hàng tháng để đánh giá xếp loại đối với cán bộ, viên chức, người lao động hằng năm.','Kết quả đánh giá xếp loại cả năm là kết quả của các tháng được xếp loại chia cho 12 tháng (tổng số điểm của các tháng xếp loại trong năm/12).','text',7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-ii-dieu-14','qcdgxl-chuong-ii','chuong-ii-dieu-14','Điều 14. Biểu mẫu','- Phụ lục 01: Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức lãnh đạo, quản lý.

- Phụ lục 02: Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức, người lao động.

- Phụ lục 03: Biên bản họp đánh giá, xếp loại hàng tháng của phòng chuyên môn.

- Phụ lục 04: Bảng tổng hợp kết quả đánh giá, xếp loại đối với cán bộ, viên chức, người lao động của phòng chuyên môn.

- Phụ lục 05: Bảng tổng hợp, rà soát kết quả đánh giá, xếp loại.

- Phụ lục 06: Báo cáo kết quả thực hiện nhiệm vụ và kế hoạch tháng …

- Phụ lục 07: Báo cáo tiến độ xử lý văn bản trên Hệ thống quản lý hồ sơ công việc; xử lý hồ sơ qua Bộ phận một cửa,

- Phụ lục 08: Báo cáo chấp hành kỷ luật, kỷ cương hành chính;.

#','text',8),('chuong-iii-dieu-15','qcdgxl-chuong-iii','chuong-iii-dieu-15','Điều 15. Trách nhiệm của viên chức, người lao động','1. Thực hiện nghiêm các quy định về đánh giá, xếp loại viên chức, người lao động. Phản ánh kịp thời việc thực hiện đánh giá, xếp loại tại các phòng chuyên môn chưa đúng hoặc chưa nghiêm túc với Ban Giám đốc Ban QLDA tỉnh.

2. Được quyền bảo lưu ý kiến về kết quả đánh giá, xếp loại hàng tháng của mình và có quyền phản ánh với Lãnh đạo Ban QLDA trong trường hợp không đồng ý với quyết định mức xếp loại đối với bản thân, nhưng phải chấp hành kết luận, nhận xét, đánh giá của cấp có thẩm quyền.

3. Xây dựng kế hoạch thực hiện hàng tháng, quý, cả năm; báo cáo kết quả thực hiện trong tháng. Nộp kế hoạch năm trong quý I; kế hoạch tháng trước ngày 05 của tháng; báo cáo kết quả thực hiện trong tháng trước ngày 25 hàng tháng qua Lãnh đạo phòng để tập hợp gửi phòng Kế hoạch - Đâu thầu tổng hợp, tham mưu báo cáo Ban QLDA.','text',1),('chuong-iii-dieu-16','qcdgxl-chuong-iii','chuong-iii-dieu-16','Điều 16. Trách nhiệm của các phòng chuyên môn','1. Trưởng phòng có trách nhiệm:

1) Phổ biến đến toàn thể viên chức, người lao động và thực hiện đúng các quy định tại Quy chế. Chịu trách nhiệm trước Giám đốc Ban QLDA tỉnh về toàn bộ quá trình thực hiện và kết quả đánh giá, xếp loại chất lượng của viên chức, người lao động thuộc thẩm quyền quản lý, phụ trách trực tiếp. Lập kế hoạch công tác hàng tháng, quý, năm của phòng trên cơ sở Kế hoạch khung hàng năm của Ban QLDA, nhiệm vụ chuyên môn của phòng và khối lượng công việc tồn đọng.','text',2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,title=EXCLUDED.title;
INSERT INTO public.regulation_articles (id,chapter_id,code,title,content,content_type,sort_order) VALUES ('chuong-iii-dieu-17','qcdgxl-chuong-iii','chuong-iii-dieu-17','Điều 17. Trách nhiệm của phòng Hành chính \- Tổng hợp','1. Tổng hợp thông tin, kết quả chấm điểm thi đua, xếp loại cán bộ, viên chức, người lao động tham mưu, báo cáo, trình Hội đồng thi đua, khen thưởng, đánh giá, xếp loại Ban QLDA xem xét, quyết định. Thông báo công khai kết quả xếp loại tại Hội nghị viên chức, người lao động hoặc qua hệ thống thông tin nội bộ.

2. Phòng Hành chính – Tổng hợp căn cứ kết quả xếp loại hàng năm thực hiện tham mưu chế độ tiền thưởng, chi thu nhập tăng thêm cho viên chức, người lao động theo đúng quy định hiện hành.

3. Lưu trữ đầy đủ hồ sơ, tài liệu về đánh giá, xếp loại theo quy định.','text',3),('chuong-iii-dieu-18','qcdgxl-chuong-iii','chuong-iii-dieu-18','Điều 18. Điều khoản thi hành','1. Lãnh đạo các phòng và cán bộ, viên chức, người lao động thuộc Ban quản lý dự án có trách nhiệm triển khai, tổ chức thực hiện Quy chế này kể từ ngày có hiệu lực.

2. Trong quá trình tổ chức thực hiện, nếu có vấn đề vướng mắc trưởng các phòng kịp thời tổng hợp, báo cáo lãnh đạo Ban quan lý dự án (qua phòng Hành chính - Tổng hợp) để kịp thời xem xét, điều chỉnh, bổ sung cho phù hợp./.

